  const ci = (xs: number[]): number => {
    const n = xs.length; const m = mean(xs); if (n < 2) return NaN;
    const v = xs.reduce((x, y) => x + (y - m) ** 2, 0) / (n - 1);
    return 1.959964 * Math.sqrt(v / n);
   };
