input.newString:
if (PAIR.length === 2) {
  const [a, b] = await Promise.all([scan(PAIR[0]), scan(PAIR[1])]);
  show(a); show(b);
   // Paired difference needs the records themselves, not the aggregates.
  const read = async (id: string): Promise<Map<number, GameRecord>> => {
    const m = new Map<number, GameRecord>();
    const rl = createInterface({ input: createReadStream(pathOf(id)), crlfDelay: Infinity });
    for await (const line of rl) {
      if (!line) continue;
      const r = JSON.parse(line) as GameRecord;
      if (m.has(r.gameId)) throw new Error(`conditions: ${id} has duplicate gameId ${r.gameId}`);
      m.set(r.gameId, r);
     }
    return m;
   };
  const [A, B] = await Promise.all([read(PAIR[0]), read(PAIR[1])]);
  const shared = [...A.keys()].filter(i => B.has(i));
  const unmatchedA = [...A.keys()].filter(i => !B.has(i)).length;
  const unmatchedB = [...B.keys()].filter(i => !A.has(i)).length;
  // A shared gameId must agree on the four fields that fix the start; same seeds do not
  // guarantee identical played openings under different rules, so this is a common start/seed.
  const FIELDS: [keyof GameRecord, string][] = [
     ['startFen', 'startFen'],
     ['seed', 'seed'],
     ['openingPlies', 'openingPlies'],
     ['colourSwapped', 'colourSwapped'],
    ];
  for (const i of shared) {
    const ra = A.get(i)!, rb = B.get(i)!;
    for (const [field, label] of FIELDS) {
      if (ra[field] !== rb[field]) throw new Error(`conditions: gameId ${i} ${label} differs between ${PAIR[0]} and ${PAIR[1]}`);
     }
    }
  const mean = (xs: number[]): number => xs.reduce((x, y) => x + y, 0) / (xs.length || 1);
  const ci = (xs: number[]): number => {
    const n = xs.length; const m = mean(xs); if (n < 2) return NaN;
    const v = xs.reduce((x, y) => x + (y - m) ** 2, 0) / (n - 1);
    return 1.959964 * Math.sqrt(v / n);
   };
  const diff = (f: (r: GameRecord) => number): [number, number] => {
    const xs = shared.map(i => f(A.get(i)!) - f(B.get(i)!));
    return [mean(xs), ci(xs)];
   };
  console.log(`\npaired ${shared.length} games (${PAIR[0]} minus ${PAIR[1]}) · unmatched A ${unmatchedA} · unmatched B ${unmatchedB}`);
  if (shared.length === 0) {
    console.log('  no estimate available (no shared gameIds)');
    return;
   }
  const [res, resCI] = diff(r => r.result);
  const [dec, decCI] = diff(r => (r.result !== 0.5 ? 1 : 0));
  const [ply, plyCI] = diff(r => r.plies);
  if (shared.length === 1) {
    console.log(`  result ${res >= 0 ? '+' : ''}${res.toFixed(3)} · decisive ${dec >= 0 ? '+' : ''}${dec.toFixed(3)} · plies ${ply >= 0 ? '+' : ''}${ply.toFixed(1)} (one pair: descriptive mean only, interval unavailable)`);
    return;
   }
  console.log(`  result ${res >= 0 ? '+' : ''}${res.toFixed(3)} ± ${resCI.toFixed(3)} · decisive ${dec >= 0 ? '+' : ''}${dec.toFixed(3)} ± ${decCI.toFixed(3)} · plies ${ply >= 0 ? '+' : ''}${ply.toFixed(1)} ± ${plyCI.toFixed(1)} (per-game interval, not setup-clustered)`);
  return;
 }

